rawdata = ""

tesdata = ""

tesdata = tesdata.lower()
def compare_strings(str1, str2):
    # 遍历字符串中的每个字符
    for i in range(len(str1)):
        if str1[i] != str2[i]:
            # 返回第一个不同字符的位置（从1开始计数）
            return f"第一个不同的地方在第{i+1}个位置"

print(compare_strings(rawdata,tesdata))

